"""Reproduce the spring bibliography from opened primary-source metadata.

The annote field records the distinction between metadata and reading a result.
Root-owned Sz.-Nagy--Foias, Domar and Ma entries are intentionally not duplicated.
"""
from pathlib import Path

P=Path(__file__).resolve().parent
entries=[]
def add(key, typ='article', **fields):
    entries.append('@'+typ+'{'+key+',\n'+',\n'.join('  '+k+' = {'+v+'}' for k,v in fields.items())+'\n}\n')

